revoke insert,update,delete,truncate,references,trigger on public.lp_orgs,public.lp_members,public.lp_snapshots,public.lp_audit,public.lp_review_events from authenticated;
alter table public.lp_review_events add column snapshot_version bigint not null default 0;
alter table public.lp_review_events add column assessment_sha256 text not null default '';
create or replace function lp_private.review(organization uuid,assessment text,review_action text,review_note text) returns uuid language plpgsql security definer set search_path='' as $$ declare event uuid; bound_version bigint; bound_hash text; begin if auth.uid() is null or lp_private.member_role(organization) is null then raise exception 'Organization access required';end if;if review_action in('approve','reject','assign') and lp_private.member_role(organization) not in('reviewer','admin') then raise exception 'Reviewer role required';end if;perform pg_advisory_xact_lock(hashtextextended(organization::text,0));select s.version,encode(extensions.digest(a::text,'sha256'),'hex') into bound_version,bound_hash from public.lp_snapshots s,jsonb_array_elements(s.payload->'assessments') a where s.org_id=organization and a->>'id'=assessment;if not exists(select 1 from public.lp_snapshots s,jsonb_array_elements(s.payload->'assessments') a where s.org_id=organization and a->>'id'=assessment)then raise exception 'Assessment not in cloud workspace';end if;insert into public.lp_review_events(org_id,assessment_id,action,note,actor,snapshot_version,assessment_sha256)values(organization,assessment,review_action,review_note,auth.uid(),bound_version,bound_hash)returning id into event;insert into public.lp_audit(org_id,actor,action,details)values(organization,auth.uid(),'review_recorded',jsonb_build_object('assessment',assessment,'event',event));return event;end $$;
